          break;
        case 'table':
          for (const h of block.headers) {
            text += extractInlineText(h.children);
          }
          for (const row of block.rows) {
            for (const cell of row) {
              text += extractInlineText(cell.children);
            }
          }
          break;
        case 'hr':
          break;
        case 'image':
          text += block.alt;
          break;
      }
    }
